insert into public.pt_decks (id, name, descr, level_from, level_to, sort)
insert into public.pt_words (id, deck_id, word, pos, ru, ex, exru, note, level, tema, sort, uk, exuk, noteuk, en, exen, noteen) values
('w:repertório','b1','o repertório','сущ.','репертуар; набор приёмов','O grupo tem um repertório muito variado de fado.','У группы очень разнообразный репертуар фаду.','','B1','B4',0,'репертуар; набір прийомів','У гурту дуже різноманітний репертуар фаду.','','repertoire; range of tricks','The group has a very varied fado repertoire.',''),
('w:leque','b1','o leque','сущ.','веер; спектр','A escola oferece um leque alargado de atividades.','Школа предлагает широкий спектр занятий.','Переносное «набор» встречается чаще прямого «веер»','B1','A5',1,'віяло; спектр','Школа пропонує широкий спектр занять.','Переносне «набір» трапляється частіше за пряме «віяло»','fan; range','The school offers a wide range of activities.','The figurative range is commoner than the literal fan'),
('w:pormenor','b1','o pormenor','сущ.','подробность, деталь','Contou-me a história com todos os pormenores.','Он рассказал мне историю со всеми подробностями.','В Португалии обычнее, чем detalhe','B1','A8',2,'подробиця, деталь','Він розповів мені історію з усіма подробицями.','У Португалії звичніше, ніж detalhe','detail','He told me the story in every detail.','Commoner in Portugal than detalhe'),
('w:ação','b1','a ação','сущ.','действие; акция','É preciso passar das palavras à ação.','Нужно перейти от слов к делу.','','B1','A1',3,'дія; акція','Треба перейти від слів до дії.','','action; a share in a company','We need to move from words to action.',''),
('w:autonomia','b1','a autonomia','сущ.','самостоятельность; автономия','Os alunos ganham autonomia ao longo do curso.','Ученики обретают самостоятельность в течение курса.','','B1','B1',4,'самостійність; автономія','Учні здобувають самостійність упродовж курсу.','','independence; autonomy','Pupils gain independence over the course.',''),
('w:bens','b1','os bens','сущ.','имущество, добро','Ele deixou todos os bens aos filhos mais novos.','Он оставил всё имущество младшим детям.','Обычно во множественном числе','B1','B9',5,'майно, добро','Він залишив усе майно молодшим дітям.','Зазвичай у множині','possessions, property','He left all his property to his younger children.','Usually in the plural'),
('w:lar','b1','o lar','сущ.','домашний очаг','Depois de uma longa viagem, é bom voltar ao lar.','После долгой поездки приятно вернуться домой.','Дом как очаг; здание — casa','B1','B2',6,'домашнє вогнище','Після довгої подорожі приємно повернутися додому.','Дім як вогнище; будівля — casa','home, hearth','After a long trip it''s good to come home.','Home as a hearth; the building is casa'),
('w:localidade','b1','a localidade','сущ.','населённый пункт','A localidade tem apenas duzentos habitantes no inverno.','В этом посёлке зимой всего двести жителей.','','B1','B2',7,'населений пункт','У цьому селищі взимку лише двісті мешканців.','','town, settlement','The town has only two hundred inhabitants in winter.',''),
('w:beco','b1','o beco','сущ.','переулок, тупик','O restaurante fica num beco estreito de Alfama.','Ресторан находится в узком переулке Алфамы.','beco sem saída — тупик, в том числе переносно','B1','B2',8,'провулок, глухий кут','Ресторан розташований у вузькому провулку Алфами.','beco sem saída — глухий кут, і переносно теж','alley, dead end','The restaurant is in a narrow alley in the Alfama.','beco sem saída — a dead end, also figuratively'),
('w:mobiliário','b1','o mobiliário','сущ.','мебель, обстановка','Compraram o mobiliário todo numa loja de usados.','Они купили всю мебель в комиссионном магазине.','Собирательное; один предмет — o móvel','B1','B2',9,'меблі, умеблювання','Вони купили всі меблі в комісійному магазині.','Збірне; один предмет — o móvel','furniture, furnishings','They bought all the furniture at a second-hand shop.','Collective; a single piece is o móvel'),
('w:posto','b1','o posto','сущ.','пункт; должность','Há um posto de combustível a dois quilómetros daqui.','Заправка есть в двух километрах отсюда.','','B1','B3',10,'пункт; посада','Заправка є за два кілометри звідси.','','station, post; position','There''s a petrol station two kilometres from here.',''),
('w:sabedoria','b1','a sabedoria','сущ.','мудрость','A minha avó dava conselhos com muita sabedoria.','Моя бабушка давала советы с большой мудростью.','','B1','A8',11,'мудрість','Моя бабуся давала поради з великою мудрістю.','','wisdom','My grandmother gave advice with great wisdom.',''),
('w:sobrevivência','b1','a sobrevivência','сущ.','выживание','A água é essencial para a sobrevivência da aldeia.','Вода необходима для выживания деревни.','','B1','A1',12,'виживання','Вода необхідна для виживання села.','','survival','Water is essential to the village''s survival.',''),
('w:abrigo','b1','o abrigo','сущ.','укрытие, приют','Procurámos abrigo da chuva debaixo de uma árvore.','Мы искали укрытие от дождя под деревом.','','B1','B2',13,'укриття, притулок','Ми шукали укриття від дощу під деревом.','','shelter','We took shelter from the rain under a tree.',''),
('w:azulejo','b1','o azulejo','сущ.','изразец, плитка азулежу','As paredes da estação estão cobertas de azulejos azuis.','Стены вокзала покрыты синими изразцами.','Символ португальской архитектуры','B1','B2',14,'кахля, азулежу','Стіни вокзалу вкриті синіми кахлями.','Символ португальської архітектури','azulejo, glazed tile','The station walls are covered in blue tiles.','An emblem of Portuguese architecture'),
('w:brinde','b1','o brinde','сущ.','тост; подарок при покупке','Fizemos um brinde à saúde dos noivos.','Мы подняли тост за здоровье молодожёнов.','','B1','B4',15,'тост; подарунок при покупці','Ми підняли тост за здоров’я молодят.','','toast; free gift','We drank a toast to the bride and groom.',''),
('w:confusão','b1','a confusão','сущ.','путаница; суматоха','Houve uma grande confusão à saída do estádio.','На выходе со стадиона была большая суматоха.','','B1','A8',16,'плутанина; метушня','На виході зі стадіону була велика метушня.','','confusion; commotion','There was a great commotion as people left the stadium.',''),
('w:cumprimento','b1','o cumprimento','сущ.','приветствие; исполнение','Deixou um cumprimento simpático antes de sair.','Уходя, он приветливо попрощался.','Второе значение — соблюдение обязательства','B1','A8',17,'вітання; виконання','Ідучи, він привітно попрощався.','Друге значення — виконання зобов’язання','greeting; fulfilment','He left a friendly greeting before going.','The second sense is keeping an obligation'),
('w:esquema','b1','o esquema','сущ.','схема; план действий','Fizemos um esquema para organizar melhor o trabalho.','Мы составили схему, чтобы лучше организовать работу.','','B1','A8',18,'схема; план дій','Ми склали схему, щоб краще організувати роботу.','','diagram; plan of action','We drew up a plan to organise the work better.',''),
('w:estúdio','b1','o estúdio','сущ.','студия','A banda gravou o disco num estúdio no Porto.','Группа записала альбом в студии в Порту.','','B1','B4',19,'студія','Гурт записав платівку в студії в Порту.','','studio','The band recorded the album in a studio in Porto.',''),
('w:horta','b1','a horta','сущ.','огород','O meu avô cultiva tomates e couves na horta.','Мой дед выращивает помидоры и капусту на огороде.','Овощи — horta, цветы и деревья — jardim','B1','B2',20,'город','Мій дід вирощує помідори й капусту на городі.','Овочі — horta, квіти й дерева — jardim','vegetable garden','My grandfather grows tomatoes and cabbages in the garden.','Vegetables go in a horta, flowers in a jardim'),
('w:impacto','b1','o impacto','сущ.','воздействие, влияние','A notícia teve um grande impacto na cidade toda.','Новость произвела сильное впечатление на весь город.','','B1','A9',21,'вплив, ефект','Новина справила сильне враження на все місто.','','impact','The news had a big impact on the whole city.',''),
('w:incêndio','b1','o incêndio','сущ.','пожар','Os bombeiros combateram o incêndio durante toda a noite.','Пожарные боролись с огнём всю ночь.','','B1','B2',22,'пожежа','Пожежники боролися з вогнем цілу ніч.','','blaze, major fire','The firefighters fought the blaze all night.',''),
('w:naturalidade','b1','a naturalidade','сущ.','место рождения; естественность','No formulário pede-se o nome e a naturalidade.','В анкете просят имя и место рождения.','В документах — именно место рождения','B1','B1',23,'місце народження; природність','В анкеті просять ім’я і місце народження.','У документах — саме місце народження','place of birth; naturalness','The form asks for your name and place of birth.','On documents it means place of birth'),
('w:parcela','b1','a parcela','сущ.','часть, доля','Uma parcela dos lucros vai para uma instituição de caridade.','Часть прибыли идёт на благотворительность.','','B1','A5',24,'частка, доля','Частина прибутку йде на благодійність.','','a portion, a part of a whole','A portion of the profits goes to a charity.',''),
('w:pausa','b1','a pausa','сущ.','перерыв, пауза','Vamos fazer uma pausa de dez minutos para café.','Давайте сделаем перерыв на десять минут на кофе.','','B1','A4',25,'перерва, пауза','Зробімо перерву на десять хвилин на каву.','','break, pause','Let''s take a ten minute break for coffee.',''),
('w:planalto','b1','o planalto','сущ.','плоскогорье','O planalto central é bastante frio no inverno.','Центральное плоскогорье зимой довольно холодное.','','B1','B2',26,'плоскогір’я','Центральне плоскогір’я взимку доволі холодне.','','plateau, tableland','The central plateau is rather cold in winter.',''),
('w:planície','b1','a planície','сущ.','равнина','O Alentejo é uma planície coberta de sobreiros.','Алентежу — равнина, покрытая пробковыми дубами.','','B1','B2',27,'рівнина','Алентежу — рівнина, вкрита корковими дубами.','','plain','The Alentejo is a plain covered in cork oaks.',''),
('w:prioridade','b1','a prioridade','сущ.','приоритет','A segurança das crianças é a nossa maior prioridade.','Безопасность детей — наш главный приоритет.','','B1','A7',28,'пріоритет','Безпека дітей — наш найбільший пріоритет.','','priority','Children''s safety is our highest priority.',''),
('w:proporção','b1','a proporção','сущ.','соотношение, доля','A proporção de mulheres na equipa aumentou este ano.','Доля женщин в команде в этом году выросла.','','B1','A5',29,'співвідношення, частка','Частка жінок у команді цього року зросла.','','proportion, ratio','The proportion of women in the team rose this year.',''),
('w:quartel','b1','o quartel','сущ.','казарма; пожарная часть','O quartel dos bombeiros fica ao lado da escola.','Пожарная часть находится рядом со школой.','','B1','B9',30,'казарма; пожежна частина','Пожежна частина розташована поруч зі школою.','','barracks; fire station','The fire station is next to the school.',''),
('w:rota','b1','a rota','сущ.','маршрут, курс','O navio mudou de rota por causa da tempestade.','Судно изменило курс из-за шторма.','','B1','B5',31,'маршрут, курс','Судно змінило курс через шторм.','','route, course','The ship changed course because of the storm.',''),
('w:selva','b1','a selva','сущ.','джунгли','Os exploradores atravessaram a selva a pé.','Исследователи пересекли джунгли пешком.','','B1','B2',32,'джунглі','Дослідники перетнули джунглі пішки.','','jungle','The explorers crossed the jungle on foot.',''),
('w:síntese','b1','a síntese','сущ.','краткое изложение','Faça uma síntese do texto em dez linhas.','Изложите текст кратко в десяти строках.','','B1','A8',33,'стислий виклад','Викладіть текст стисло в десяти рядках.','','summary, synopsis','Summarise the text in ten lines.',''),
('w:tensão','b1','a tensão','сущ.','напряжение','A tensão entre os dois vizinhos aumentou muito.','Напряжение между двумя соседями сильно возросло.','','B1','B6',34,'напруга','Напруга між двома сусідами дуже зросла.','','tension','The tension between the two neighbours grew a lot.',''),
('w:transeunte','b1','o transeunte','сущ.','прохожий','Um transeunte ajudou-me a encontrar a rua certa.','Прохожий помог мне найти нужную улицу.','','B1','B2',35,'перехожий','Перехожий допоміг мені знайти потрібну вулицю.','','passer-by','A passer-by helped me find the right street.',''),
('w:disponibilidade','b1','a disponibilidade','сущ.','готовность; наличие времени','Agradeço a sua disponibilidade para me receber hoje.','Благодарю за то, что нашли время принять меня сегодня.','','B1','A4',36,'готовність; наявність часу','Дякую, що знайшли час прийняти мене сьогодні.','','availability, willingness','Thank you for finding time to see me today.',''),
('w:aço','b1','o aço','сущ.','сталь','A ponte nova é feita de aço e betão.','Новый мост сделан из стали и бетона.','','B1','A6',37,'сталь','Новий міст зроблений зі сталі й бетону.','','steel','The new bridge is made of steel and concrete.',''),
('w:acréscimo','b1','o acréscimo','сущ.','прибавка, увеличение','Houve um acréscimo de dez por cento no preço.','Цена выросла на десять процентов.','','B1','A5',38,'надбавка, приріст','Ціна зросла на десять відсотків.','','an addition, an extra amount','The price rose by ten per cent.',''),
('w:acusação','b1','a acusação','сущ.','обвинение','A acusação não apresentou provas suficientes ao tribunal.','Обвинение не представило суду достаточных доказательств.','','B1','B9',39,'звинувачення','Звинувачення не надало суду достатніх доказів.','','accusation; the prosecution','The prosecution gave the court insufficient evidence.',''),
('w:acusado','b1','o acusado','сущ.','обвиняемый','O acusado negou tudo perante o juiz.','Обвиняемый всё отрицал перед судьёй.','','B1','B9',40,'обвинувачений','Обвинувачений усе заперечував перед суддею.','','the accused','The accused denied everything before the judge.',''),
('w:alarme','b1','o alarme','сущ.','сигнализация; тревога','O alarme do carro tocou a meio da noite.','Сигнализация машины сработала посреди ночи.','','B1','B2',41,'сигналізація; тривога','Сигналізація машини спрацювала посеред ночі.','','alarm','The car alarm went off at midnight.',''),
('w:alerta','b1','o alerta','сущ.','предупреждение, оповещение','Foi lançado um alerta de mau tempo para amanhã.','Объявлено предупреждение о непогоде на завтра.','','B1','A8',42,'застереження, сповіщення','Оголошено попередження про негоду на завтра.','','alert, warning','A bad weather alert has been issued for tomorrow.',''),
('w:alicerce','b1','o alicerce','сущ.','фундамент, основа','A confiança é o alicerce de qualquer amizade.','Доверие — основа любой дружбы.','','B1','B2',43,'фундамент, основа','Довіра — основа будь-якої дружби.','','foundation','Trust is the foundation of any friendship.',''),
('w:amante','b1','o amante','сущ.','любитель; любовник','É um grande amante de música clássica.','Он большой любитель классической музыки.','','B1','B1',44,'любитель; коханець','Він великий любитель класичної музики.','','enthusiast; lover','He is a great lover of classical music.',''),
('w:ambiguidade','b1','a ambiguidade','сущ.','двусмысленность','A resposta dele deixou alguma ambiguidade no ar.','Его ответ оставил некоторую двусмысленность.','','B1','A8',45,'двозначність','Його відповідь залишила певну двозначність.','','ambiguity','His answer left a certain ambiguity in the air.',''),
('w:amortecedor','b1','o amortecedor','сущ.','амортизатор','O mecânico disse que o amortecedor está partido.','Механик сказал, что амортизатор сломан.','','B1','B5',46,'амортизатор','Механік сказав, що амортизатор зламаний.','','shock absorber','The mechanic said the shock absorber is broken.',''),
('w:amostra','b1','a amostra','сущ.','образец, проба','O laboratório analisou uma amostra da água do rio.','Лаборатория проанализировала пробу речной воды.','','B1','A5',47,'зразок, проба','Лабораторія проаналізувала пробу річкової води.','','sample','The laboratory analysed a sample of river water.',''),
('w:ampliação','b1','a ampliação','сущ.','расширение','A ampliação da escola vai começar em setembro.','Расширение школы начнётся в сентябре.','','B1','A5',48,'розширення','Розширення школи почнеться у вересні.','','extension, enlargement','The extension to the school starts in September.',''),
('w:anjo','b1','o anjo','сущ.','ангел','Na igreja há uma pintura antiga com dois anjos.','В церкви есть старинная картина с двумя ангелами.','','B1','A1',49,'ангел','У церкві є старовинна картина з двома ангелами.','','angel','In the church there''s an old painting with two angels.',''),
('w:aposta','b1','a aposta','сущ.','ставка, пари','Perdi a aposta e tive de pagar o jantar.','Я проиграл пари и должен был оплатить ужин.','','B1','B4',50,'ставка, парі','Я програв парі й мусив оплатити вечерю.','','bet, wager','I lost the bet and had to pay for dinner.',''),
('w:armadilha','b1','a armadilha','сущ.','ловушка','A última pergunta do exame era uma armadilha.','Последний вопрос экзамена был ловушкой.','','B1','B4',51,'пастка','Останнє питання іспиту було пасткою.','','trap','The last exam question was a trap.',''),
('w:armazém','b1','o armazém','сущ.','склад','As mercadorias ficam no armazém até sexta-feira.','Товар лежит на складе до пятницы.','','B1','B7',52,'склад','Товар лежить на складі до п’ятниці.','','warehouse','The goods stay in the warehouse until Friday.',''),
('w:arquipélago','b1','o arquipélago','сущ.','архипелаг','O arquipélago dos Açores tem nove ilhas habitadas.','Азорский архипелаг состоит из девяти обитаемых островов.','','B1','B2',53,'архіпелаг','Азорський архіпелаг складається з дев’яти населених островів.','','archipelago','The Azores archipelago has nine inhabited islands.',''),
